const D = { density:.55, scale:1, energy:.6, speed:1, hue:40, trail:.55, tilt:.5, x:.5, y:.5, style:'brass', act:'clockwork', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const st = P.style;
const MAXP = 11;
const intn = (K.intensity!=null?K.intensity:0.6);

// seed-dependent planet family
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.pl = [];
  for (let i=0;i<MAXP;i++){
    S.pl.push({
      rf: 0.17 + (i+1)/(MAXP+0.4)*0.82,     // radius fraction of outer extent
      ph: fr(i*3+1)*6.283,                   // start phase
      hu: fr(i*3+2)*360,                     // per-planet hue jitter
      sz: 0.6 + fr(i*3+3)*1.1,               // relative body size
      moon: fr(i*3+7)>0.62                    // some planets get a moon
    });
  }
  S.trails = null;
}
const nP = Math.max(2, Math.round(3 + P.density*(MAXP-3)));
if (!S.trails || S.trails.length!==MAXP){ S.trails = []; for(let i=0;i<MAXP;i++) S.trails.push([]); }

// -------- cached background field (stars + nebula/vignette + paper) keyed on size+seed+style --------
const bgKey = width+'x'+height+'_'+P.seed+'_'+st;
if (!S.bg || S.bgKey !== bgKey){
  S.bg = createGraphics(width,height);
  const g = S.bg; g.colorMode(g.HSB,360,100,100,100); g.noStroke();
  const cx=width/2, cy=height/2, mx=Math.max(width,height)*0.72;
  const paper = (st==='ink');
  const steps = 64;
  for (let s=steps;s>=0;s--){
    const rr = mx*s/steps, f = s/steps;
    if (paper) g.fill(41, 10 - f*4, 92 - f*8, 100);
    else if (st==='blueprint') g.fill(214, 66+f*10, 20 - f*13, 100);
    else if (st==='neon') g.fill(275, 60+f*20, 15 - f*10, 100);
    else if (st==='xray') g.fill(200, 40+f*30, 13 - f*8, 100);
    else g.fill(32, 46+f*22, 16 - f*11, 100); // brass warm brown vignette
    g.ellipse(cx,cy,rr*2,rr*2);
  }
  // starfield / grain
  const nst = Math.floor((width*height)/5200);
  for (let i=0;i<nst;i++){
    const sx=fr(i*2+900)*width, sy=fr(i*2+901)*height, b=fr(i+1300);
    if (paper){ g.fill(38,18,40,30+b*40); g.ellipse(sx,sy,0.8+b*0.8,0.8+b*0.8); }
    else if (st==='blueprint'){ if(b>0.85){ g.fill(205,20,96,50); g.ellipse(sx,sy,1,1);} }
    else { g.fill(45,10,95,20+b*70); const d=0.6+b*1.6; g.ellipse(sx,sy,d,d); }
  }
  S.bgKey = bgKey;
}
image(S.bg,0,0);

// -------- orrery geometry (all live so scale/density poke instantly) --------
const cx = P.x*width, cy = P.y*height;
const R = u*0.46*P.scale;
const squash = 1 - 0.72*constrain(P.tilt,0,1);   // orbital-plane tilt (edge-on when high)
const plane = S.hbase!=null?S.hbase:(S.hbase=fr(77)*0.5); // slight fixed rotation of plane
const glow = 0.35 + P.energy*0.65 + A.rms*0.9;
const paper = (st==='ink'), wire = (st==='xray'), blue = (st==='blueprint'), neon = (st==='neon');
const inkline = paper?[38,60,18]:blue?[205,30,96]:wire?[196,55,90]:neon?[P.hue,80,96]:[40,58,86];

// act -> orbital speed shaping
let spd = P.speed;
if (P.act==='conjunction') spd = P.speed*(0.4 + intn*1.3);     // surges pull planets toward alignment feel
else if (P.act==='drift') spd = P.speed*0.5;

push();
translate(cx,cy);
rotate(plane + K.t*0.008*P.speed);

// graduated outer dial ring + ticks (engraved instrument)
const dialR = R*0.995;
noFill();
if (neon||wire) blendMode(ADD);
stroke(inkline[0],inkline[1],inkline[2], neon?60:70);
strokeWeight(neon?1.6:1.1);
ellipse(0,0,dialR*2, dialR*2*squash);
ellipse(0,0,dialR*2*0.965, dialR*2*0.965*squash);
const ticks = Math.floor(48 + P.density*40);
strokeWeight(0.9);
for (let i=0;i<ticks;i++){
  const a = i/ticks*6.283;
  const major = (i% (Math.max(2,Math.floor(ticks/12))) ===0);
  const r0 = dialR*(major?0.945:0.968), r1 = dialR;
  const c=Math.cos(a), s=Math.sin(a);
  stroke(inkline[0],inkline[1],inkline[2], major?85:45);
  line(c*r0, s*r0*squash, c*r1, s*r1*squash);
}
blendMode(BLEND);

// orbit rings + planets
for (let i=0;i<nP;i++){
  const pl = S.pl[i];
  const r = R*pl.rf;
  // orbit ring
  noFill();
  const ringB = paper?22:blue?40:wire?32:neon?38:44;
  if (neon||wire) blendMode(ADD);
  stroke(paper?38:blue?205:wire?196:neon?(P.hue+i*12)%360:38, paper?46:blue?45:wire?50:neon?70:40, paper?26:ringB+10, paper?60:blue?55:wire?46:neon?42:52);
  strokeWeight(paper?1.0:0.9);
  ellipse(0,0, r*2, r*2*squash);
  blendMode(BLEND);
  // Kepler-ish differential speed (continuous via K.t -> never re-phases)
  const w = 0.20 * Math.pow(0.5/Math.max(0.12,pl.rf), 1.5);
  const ang = pl.ph + K.t*spd*w;
  const px = Math.cos(ang)*r, py = Math.sin(ang)*r*squash;
  // trail history
  const tr = S.trails[i];
  tr.push([px,py]);
  const tlen = Math.floor(6 + P.trail*40);
  while (tr.length>tlen) tr.shift();
  // draw trail
  if (neon||wire||!paper) blendMode(ADD);
  for (let k=1;k<tr.length;k++){
    const f = k/tr.length;
    const a0 = f*(neon?55:38)*(0.4+glow*0.6);
    stroke((pl.hu*0.3 + P.hue + i*8)%360, paper?30:70, paper?24:88, a0);
    strokeWeight((paper?1.2:1.4)*f);
    line(tr[k-1][0],tr[k-1][1], tr[k][0],tr[k][1]);
  }
  blendMode(BLEND);
  // planet body
  const bodyR = u*0.017*P.scale*pl.sz*(0.8+P.density*0.5);
  const hue = (P.hue + pl.hu*0.28 + i*6)%360;
  const kick = K.pulse*0.4 + A.bass*0.6;
  push();
  translate(px,py);
  if (wire){
    noFill(); stroke(196,55,92,80); strokeWeight(1.1); ellipse(0,0,bodyR*2,bodyR*2);
    stroke(196,40,80,50); line(-bodyR,0,bodyR,0); line(0,-bodyR,0,bodyR);
  } else if (paper){
    // stipple/hatch sphere
    noStroke();
    for (let s2=0;s2<26;s2++){ const aa=fr(i*40+s2)*6.283, rr=Math.sqrt(fr(i*41+s2))*bodyR; const sh=(Math.cos(aa)+1)*0.5; fill(38, 34, 20+sh*22, 34); ellipse(Math.cos(aa)*rr, Math.sin(aa)*rr, 1.1,1.1); }
    noFill(); stroke(38,50,16,80); strokeWeight(0.9); ellipse(0,0,bodyR*2,bodyR*2);
  } else if (blue){
    noFill(); stroke(205,30,96,90); strokeWeight(1.1); ellipse(0,0,bodyR*2,bodyR*2);
    stroke(205,25,90,55); line(-bodyR*1.3,0,bodyR*1.3,0); line(0,-bodyR*1.3,0,bodyR*1.3);
  } else {
    // modeled metallic/glowing sphere
    if (neon){ blendMode(ADD); drawingContext.shadowBlur = 12+kick*14; drawingContext.shadowColor = 'hsl('+Math.round(hue)+',90%,60%)'; }
    noStroke();
    fill(hue, neon?80:55, (neon?70:60)+glow*22+kick*18);
    ellipse(0,0, bodyR*2, bodyR*2);
    // shading highlight (brass) — offset lighter blob
    fill((hue+8)%360, neon?55:38, (neon?95:88), neon?70:80);
    ellipse(-bodyR*0.34,-bodyR*0.34, bodyR*0.9, bodyR*0.9);
    drawingContext.shadowBlur = 0; blendMode(BLEND);
  }
  // optional moon
  if (pl.moon && P.density>0.35){
    const ma = ang*3.1 + pl.ph;
    const mr = bodyR*2.4;
    const mx=Math.cos(ma)*mr, my=Math.sin(ma)*mr*squash;
    if (wire||blue){ noFill(); stroke(wire?196:205,40,90,70); strokeWeight(0.9); ellipse(mx,my,bodyR*0.7,bodyR*0.7); }
    else { noStroke(); fill(paper?38:hue, paper?20:40, paper?30:80, paper?70:90); ellipse(mx,my,bodyR*0.75,bodyR*0.75); }
  }
  pop();
}

// central sun
const sunR = u*0.032*P.scale*(1 + K.swell*0.12 + A.bass*0.25);
if (!paper && !blue && !wire){
  blendMode(ADD);
  drawingContext.shadowBlur = 22 + glow*24 + A.bass*20;
  drawingContext.shadowColor = neon?('hsl('+Math.round(P.hue)+',90%,60%)'):'hsl(44,95%,60%)';
  noStroke();
  for (let r=3;r>=1;r--){ fill(neon?P.hue:46, neon?70:60, 90, 22); ellipse(0,0, sunR*r*1.2, sunR*r*1.2); }
  fill(neon?P.hue:48, neon?40:35, 100, 95); ellipse(0,0,sunR*1.4,sunR*1.4);
  drawingContext.shadowBlur = 0; blendMode(BLEND);
} else {
  noFill(); stroke(paper?38:blue?205:196, paper?55:35, paper?18:94, 90); strokeWeight(1.4);
  ellipse(0,0,sunR*2,sunR*2);
  const rays=12; strokeWeight(0.9);
  for(let i=0;i<rays;i++){ const a=i/rays*6.283; stroke(paper?38:blue?205:196,40,paper?18:88,60); line(Math.cos(a)*sunR*1.2,Math.sin(a)*sunR*1.2, Math.cos(a)*sunR*1.7,Math.sin(a)*sunR*1.7); }
}
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
